package it.echoeswar.management.faction.entity;

import jakarta.persistence.*;

/**
 * JPA entity representing a faction, mapped to the {@code factions} table.
 *
 * <p>A faction has localized names (Italian and English) and is referenced by
 * {@code Card}, where each card belongs to exactly one faction.</p>
 */
@Entity
@Table(name="factions")
public class Faction {

    /**
     * Primary key, auto-generated by the database (identity column).
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private byte id;

    /**
     * Faction name in Italian (max 100 characters).
     */
    @Column(nullable = false, length = 100)
    private String nameIt;

    /**
     * Faction name in English (max 100 characters).
     */
    @Column(nullable = false, length = 100)
    private String nameEn;
}
